{
  "title": "LocationFormData",
  "type": "object",
  "properties": {
    "ctl00_body_txtName": {
      "type": "string",
      "description": "Location name. If the user provides a value, use that. Otherwise, fetch from the getSelectLocationDetails tool and populate this field."
