      "type": "string",
      "description": "Location abbreviation. Use user input if available, otherwise retrieve from the getSelectLocationDetails tool."
    },
    "ctl00_body_txttp": {
      "type": "string",
      "description": "Telephone number. Use user-provided input or fetch it from the getSelectLocationDetails tool if not provided."
    },
    "ctl00_body_txtFax": {
      "type": "string",
      "description": "Fax number. Use the user-entered value or retrieve it from the getSelectLocationDetails tool if not provided."
    },
    "ctl00_body_txtemail": {
      "type": "string",
      "format": "email",
      "description": "Email address. Use user input or fetch from the getSelectLocationDetails tool if left blank."
    },
    "ctl00_body_txturl": {
      "type": "string",
      "format": "uri",
      "description": "Website URL. Populate with user input or use data from the getSelectLocationDetails tool if empty."
    },
    "ctl00_body_txtaddress": {
      "type": "string",
      "description": "Address. Use the provided value or retrieve from the getSelectLocationDetails tool if not entered."
    },
    "ctl00_body_ddlCountry": {
      "type": "string",
      "description": "Country. If not specified by the user, get the value from the getSelectLocationDetails tool and you take user give the country name corresponding value take"
    },
    "ctl00_body_ddlProvince": {
      "type": "string",
      "description": "Province or state. Use user-provided input or default to the value from the getSelectLocationDetails tool and you take user give the Province name corresponding value take."
    },
    "ctl00_body_ddlDistrict": {
      "type": "string",
      "description": "District. Use input from the user or fallback to data from the getSelectLocationDetails tool and you take user give the District name corresponding value take"
    },
    "ctl00_body_cboTimeZone": {
      "type": "string",
      "description": "Time zone. Use the user-entered value or populate from the getSelectLocationDetails tool if blank."
    },
    "ctl00_body_txtHeadName": {
      "type": "string",
      "description": "Head of location name. Use user-provided value or fetch from the getSelectLocationDetails tool."
    },
    "ctl00_body_txtHTitle": {
      "type": "string",
      "description": "Head's title or designation. If not provided by the user, get it from the getSelectLocationDetails tool."
    },
    "ctl00_body_txtAdminName": {
      "type": "string",
      "description": "Administrator name. Use input from the user or fetch from the getSelectLocationDetails tool."
    },
    "ctl00_body_filMyFile": {
      "type": "string",
      "contentEncoding": "base64",
      "title": "Logo File (Binary Base64)",
      "description": "Base64-encoded logo file to be uploaded. Optional input."
    },
    "ctl00_body_butSave": {
      "type": "string",
      "enum": [
        "Save"
      ],
      "description": "Trigger to save the form. Should always be set to 'Save'."
    },
    "ctl00_body_hdnDefCountry": {
      "type": "string",
      "description": "Default country code or name. If not provided, populate from the getSelectLocationDetails tool."
    }
  },
  "required": [
    "ctl00_body_txtName",
    "ctl00_body_ddlCountry",
    "ctl00_body_ddlProvince",
    "ctl00_body_ddlDistrict"
  ]
}

